<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { listarIncidencias } from '../services/incidencias'
import type { Incidencia } from '../interfaces/incidencias.interface'
const items=ref<Incidencia[]>([]),total=ref(0),lastPage=ref(1),loading=ref(false),error=ref(''),detail=ref<Incidencia|null>(null)
const filters=reactive({criterio:'',anonima:'',desde:'',hasta:'',page:1})
const anonymousCount=computed(()=>items.value.filter(item=>['si','sí','1','true'].includes(String(item.anonima).toLowerCase())).length)
function isAnonymous(item:Incidencia){return ['si','sí','1','true'].includes(String(item.anonima).toLowerCase())}
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const response=await listarIncidencias(filters);items.value=response.data;total.value=response.total;lastPage.value=response.last_page}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudieron cargar las incidencias.'}finally{loading.value=false}}
function clear(){Object.assign(filters,{criterio:'',anonima:'',desde:'',hasta:'',page:1});load()}
function location(item:Incidencia){if(item.latitud==null||item.longitud==null)return '';return `https://www.google.com/maps?q=${item.latitud},${item.longitud}`}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Institucional / Integridad / Incidencias</nav><header class="hero"><div class="mark">INT</div><div><small>AURA · Integridad</small><h1>Incidencias y denuncias</h1><p>Consulta los reportes asociados a la programación y transporte de cisternas.</p></div><div class="metric"><b>{{total}}</b><span>reportes</span></div><div class="metric"><b>{{anonymousCount}}</b><span>anónimos en página</span></div></header><section class="notice"><b>Alcance del sistema actual</b><span>El backend Laravel solo expone la consulta de incidencias. El registro y la atención requieren nuevos endpoints antes de habilitarse en Vue.</span></section><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Placa, comentario, DNI o denunciante" @keyup.enter="load(1)"></label><label>Tipo<select v-model="filters.anonima"><option value="">Todas</option><option value="1">Anónimas</option><option value="0">Identificadas</option></select></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><button @click="load(1)">Buscar</button><button class="clear" @click="clear">Limpiar</button></section><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">Cargando incidencias…</div><div v-else-if="!items.length" class="empty">No se encontraron incidencias con los filtros indicados.</div><section v-else class="cards"><article v-for="item in items" :key="item.id"><header><div><small>Incidencia</small><b>#{{item.id}}</b></div><em :class="{anonymous:isAnonymous(item)}">{{isAnonymous(item)?'Anónima':'Identificada'}}</em></header><h2>{{item.placa||item.transporte?.placa||'Sin placa registrada'}}</h2><time>{{item.created_at}}</time><p>{{item.comentario}}</p><dl><div><dt>Programación</dt><dd>#{{item.programacion_id||'—'}}</dd></div><div><dt>Imágenes</dt><dd>{{item.imagenes?.length||0}}</dd></div></dl><button @click="detail=item">Ver incidencia</button></article></section><footer v-if="lastPage>1" class="pagination"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>Página {{filters.page}} de {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer><div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal"><header><div><small>Detalle de incidencia</small><h2>Incidencia #{{detail.id}}</h2></div><button @click="detail=null">×</button></header><div class="facts"><div><span>Fecha</span><b>{{detail.created_at}}</b></div><div><span>Placa</span><b>{{detail.placa}}</b></div><div><span>Denuncia</span><b>{{isAnonymous(detail)?'Anónima':'Identificada'}}</b></div><div v-if="!isAnonymous(detail)"><span>Denunciante</span><b>{{detail.nombre_apellido}} · {{detail.dni}}</b></div></div><h3>Comentario registrado</h3><p>{{detail.comentario}}</p><a v-if="location(detail)" :href="location(detail)" target="_blank" rel="noopener">Ver ubicación registrada ↗</a><h3>Evidencias fotográficas</h3><div v-if="detail.imagenes?.length" class="gallery"><a v-for="image in detail.imagenes" :key="image.id" :href="image.url" target="_blank"><img :src="image.url" :alt="image.nombre||'Evidencia de incidencia'"></a></div><p v-else class="no-images">No se adjuntaron imágenes.</p></section></div></div></template>
<style scoped>
