l}.cards header em.anonymous{color:#8a6412;background:#fff1cc}.cards h2{margin:10px 0 2px;font-size:.82rem}.cards time{color:#7d898f;font-size:.52rem}.cards p{min-height:42px;font-size:.59rem}.cards dl{display:flex;gap:18px}.cards dl div{display:flex;gap:5px}.cards dt,.cards dd{margin:0;font-size:.53rem}.pagination{margin-top:13px;display:flex;justify-content:center;align-items:center;gap:10px}.pagination span{font-size:.58rem}.pagination button:disabled{opacity:.45}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,660px);max-height:90vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0 15px;font-size:1rem}.modal header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.facts{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.facts div{padding:9px;border-radius:7px;background:#f4f1fc}.facts span,.facts b{display:block;font-size:.57rem}.modal h3{margin:17px 0 6px;font-size:.66rem}.modal>p{font-size:.62rem}.modal>a{color:var(--accent);font-size:.6rem}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.gallery img{width:100%;height:120px;object-fit:cover;border-radius:7px}.no-images{padding:20px;text-align:center;background:#f2f4f5}@media(max-width:850px){.cards{grid-template-columns:1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.metric{margin-left:0}}
</style>
